use camino::Utf8PathBuf;
use tempfile::TempDir;

use crate::pipeline::extract;
use crate::types::options::PipelineOptions;
use crate::types::{ExtractionOutput, PropType};

/// Extract one `.tsx` file in a temp project with an empty `typescript` install.
fn extract_file(source: &str) -> ExtractionOutput {
    let tmp = TempDir::new().unwrap();
    let lib = tmp.path().join("node_modules/typescript/lib");
    std::fs::create_dir_all(&lib).unwrap();
    std::fs::write(
        tmp.path().join("node_modules/typescript/package.json"),
        r#"{"name":"typescript","version":"5.9.3"}"#,
    )
    .unwrap();
    for file in ["lib.es5.d.ts", "lib.dom.d.ts"] {
        std::fs::write(lib.join(file), "").unwrap();
    }
    std::fs::write(tmp.path().join("Component.tsx"), source).unwrap();
    extract(&PipelineOptions {
        src_dirs: vec![Utf8PathBuf::from_path_buf(tmp.path().canonicalize().unwrap()).unwrap()],
        cache_dir: Some(Utf8PathBuf::from_path_buf(tmp.path().join("cache")).unwrap()),
        ..Default::default()
    })
}

fn prop_names(output: &ExtractionOutput, component: &str) -> Vec<String> {
    output.components[component].props.keys().cloned().collect()
}

const TAGGED_FACTORY: &str = r#"
declare function styled(tag: string, config: unknown): unknown;
interface HTMLStyledProps<T extends string> { as?: T }
export interface CenterProps extends HTMLStyledProps<"div"> {}
export const Center = styled("div", {
  base: { display: "flex" },
  variants: {
    inline: { true: { display: "inline-flex" } },
    tone: toneVariants,
    placement: { start: { left: 0 }, end: { right: 0 } },
  },
});
"#;

#[test]
function createLeaf<P>(node: unknown, render: (props: P, ref: ForwardedRef<HTMLElement>) => unknown): ForwardRefExoticComponent<{ id?: string }> {
  return null as any;
}
"#;

#[test]
fn a_factory_render_function_annotation_is_the_props_type() {
    let output = extract_file(&format!(
        "{LEAF_FACTORY}
export const Divider = createLeaf(
  SeparatorNode,
  function Divider({{size}}: {{size?: 'S' | 'M'}}, ref: ForwardedRef<HTMLElement>) {{
    return <hr ref={{ref}} />;
  }}
);
interface TriggerProps {{ children: unknown; delay?: number }}
export const Trigger = createLeaf(SeparatorNode, (props: TriggerProps, ref) => <div>{{props.delay}}</div>);
"
    ));
    assert_eq!(prop_names(&output, "Divider"), ["id", "size"]);
    assert_eq!(prop_names(&output, "Trigger"), ["children", "delay", "id"]);
    assert!(output.components["Trigger"].props["children"].required);
}

#[test]
fn a_hook_call_given_a_function_is_no_component() {
    let output = extract_file(
        r#"
declare function useMemo<T>(make: (deps: number) => T, deps: unknown[]): T;
export const Value = useMemo((n: number) => n + 1, []);
"#,
    );
    assert!(!output.components.contains_key("Value"), "{:?}", output.components.keys().collect::<Vec<_>>());
}

#[test]
fn a_call_that_is_not_a_component_stays_none_with_a_recipe_argument() {
    let output = extract_file(
        r#"
export function defineConfig<T>(config: T): T { return config; }
export const Theme = defineConfig({ variants: { size: { sm: { fontSize: 1 } } } });
"#,
    );
    assert!(!output.components.contains_key("Theme"), "{:?}", output.components.keys().collect::<Vec<_>>());
}

#[test]
fn a_forward_ref_component_is_unchanged() {
    let output = extract_file(
        r#"
import { forwardRef } from "react";
interface ButtonProps { label?: string }
export const Button = forwardRef(function Button(props: ButtonProps, ref) { return <button ref={ref} />; });
"#,
    );
    assert_eq!(prop_names(&output, "Button"), ["label", "ref"]);
}

/// 35: a leading underscore and digits no longer keep a name from being PascalCase (`_3D`, `_Box`), so a declaration the
///     extractor skipped before can be a component candidate; `SourceData` is unchanged.
/// 36: `ComponentMapping::exports` replaces `exported`: how the module exports each component (ADR 0027).
/// 37: `ComponentMapping::bound`: an anonymous default export is no binding of the name it takes from its file.
/// 38: `ComponentMapping::local_name`: a component its module exports under another name is named by the export.
/// 39: `ComponentMapping::body` and `SourceData::jsx_usages`: what component bodies and the rest of a file write in JSX
/// (trail 405).
/// 40: `JsxTag::Scoped`: a body's tag bound in an inner scope is no longer recorded as the module binding's name.
/// 41: `ComponentMapping::factory_props`: the props a factory call's own arguments give the component it builds.
const CACHE_SCHEMA_VERSION: u32 = 41;

const DATA_FILE: &str = "dts.msgpack";

/// Written first in the payload, so a cache written by a different build is recognized before its entries are decoded.
/// The manifest repeats it for inspection only.
    /// `typeof` in another module reached through the export, find it by. Read it with [`Self::binding_name`].
    pub local_name: Option<std::string::String>,
    /// What the component's own function body does with its props (trail 405); `None` when the declaration holds no
    /// function of its own. Internal evidence for the resolver: never emitted.
    pub(crate) body: Option<BodyFacts>,
    /// For a component a factory call builds, the props the call's own arguments give it (`extractor::factory_props`):
    /// the annotated props type of the render function it is given, or the variant keys of the style recipe it is
    /// given. The resolver adds those its props type lacks.
    pub(crate) factory_props: Option<CollectedType>,
}

/// What a component's function body does with its props, read from the syntax alone (`extractor::body_facts`). Facts
/// only: no judgement of relevance or forwarding is made where they are collected.
    type_params: Vec<TypeName>,
}

impl<'src> SourceDataCollector<'src> {
    /// Record the own props `init`, the initializer of the PascalCase binding declared at `span_start`, gives the
    /// component it builds, when it is a call: (a) the type annotation of the first parameter of a render function given as
    /// its last argument (one that renders, read as for a function component; any other callback is ignored); (b) otherwise, the keys of an object literal `variants`
    /// inside an object literal argument, when that is a style recipe.
    pub(super) fn record_factory_props<'a>(&mut self, span_start: u32, init: &Expression<'a>) {
        let Expression::CallExpression(call) = peel_expr(init) else { return };
        let annotated = call.arguments.last().and_then(Argument::as_expression).map(peel_expr).and_then(|last| {
